 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    # Markers project in a straight line toward a continuous colored border rail.
    rails = {}
    for r in range(h):
        if grid[r][0] != bg: rails[r] = 0
        elif grid[r][-1] != bg: rails[r] = w-1
    for r, rail in rails.items():
        for c, color in enumerate(grid[r]):
            if color == bg or c == rail:
                continue
            # Do not overwrite a different colored rail.
            step = 1 if rail > c else -1
            for k in range(c + step, rail, step):
                if grid[r][k] == bg:
                    out[r][k] = color
            out[r][c] = 4
    return out

if __name__ == '__main__':
    pass
